// Parse AI Agent output to extract follow-up actions
const llmOutput = $input.first().json.output;
console.log('🤖 AI Agent Output:', llmOutput);

try {
  // Try to parse the LLM output as JSON
  let actions;

  if (typeof llmOutput === 'string') {
    // Clean up the output if it contains markdown formatting
    const cleanOutput = llmOutput.replace(/```json\n?|```\n?/g, '').trim();
    actions = JSON.parse(cleanOutput);
  } else if (Array.isArray(llmOutput)) {
    actions = llmOutput;
  } else {
    actions = [llmOutput];
  }

  if (Array.isArray(actions) && actions.length > 0) {
    console.log(`✅ Successfully parsed ${actions.length} follow-up actions`);
    return actions.map((action, index) => ({
      json: {
        ...action,
        scheduledDate: new Date().toISOString().split('T')[0],
        status: 'scheduled',
        clinic: '{{CLINIC_NAME}}',
        actionId: `FA${Date.now()}_${index + 1}`
      }
    }));
  } else {
    console.log('ℹ️ No follow-up actions identified from visit notes');
    return [];
  }
} catch (error) {
  console.error('❌ Failed to parse AI output:', error);
  console.error('Raw output:', llmOutput);

  // Fallback: try to extract basic info and create a generic follow-up
  const visitData = $node['🔄 Triggered by Visit Completion'].json;
  if (visitData && visitData['Pet Name']) {
    return [{
      json: {
        action: 'General follow-up check',
        dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 7 days from now
        petName: visitData['Pet Name'] || 'Unknown Pet',
        status: 'scheduled',
        clinic: '{{CLINIC_NAME}}',
        actionId: `FA${Date.now()}_fallback`
      }
    }];
  }

  return [];
}

// Filter follow-ups that are due today
const today = new Date();
today.setHours(0, 0, 0, 0);
const todayStr = today.toISOString().split('T')[0];

console.log(`📅 Checking for follow-ups due on: ${todayStr}`);

const dueActions = $input.all().filter(item => {
  const dueDateStr = item.json['Due Date'];
  const status = item.json['Status'];

  // Only process scheduled actions that are due today
  if (!dueDateStr || status !== 'scheduled') {
    return false;
  }

  // Normalize dates for comparison
  const dueDate = new Date(dueDateStr);
  dueDate.setHours(0, 0, 0, 0);

  const isDue = dueDate.getTime() === today.getTime();

  if (isDue) {
    console.log(`✅ Action due today: ${item.json['Action']} for ${item.json['Pet Name']}`);
  }

  return isDue;
});

console.log(`📊 Found ${dueActions.length} actions due today`);

return dueActions.map(action => ({ json: action.json }));

